package io.github.coyotewolf.aoi.model;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.time.Instant;
import java.util.Comparator;
import java.util.List;
import java.util.UUID;

public final class Models {
    public static final Comparator<Message> MESSAGE_ORDER = Comparator.comparing(m -> Instant.parse(m.createdAt())).thenComparing(Message::id);

    public static String id() {
        return UUID.randomUUID().toString();
    }

    public static String uuid(String value) {
        if (value == null || !value.matches("(?i)[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}")) {
            throw new IllegalArgumentException("資料代碼無效。");
        }
        return value;
    }

    public static String text(JsonObject o, String key, String fallback) {
        JsonElement v = o.get(key);
        return v != null && v.isJsonPrimitive() && v.getAsJsonPrimitive().isString() ? v.getAsString() : fallback;
    }

    public static String safe(String value, int max) {
        if (value == null) {
            return "";
        }
        String s = value.replaceAll("[\\p{Cc}&&[^\\n\\t]]", "").replace('§', ' ');
        if (s.length() <= max) {
            return s;
        }
        int end = max;
        if (end > 0 && Character.isHighSurrogate(s.charAt(end - 1))) {
            --end;
        }
        return s.substring(0, end) + "…";
    }

    public static JsonArray facts(JsonObject o) {
        JsonElement f = o.get("facts");
        return f != null && f.isJsonArray() ? f.getAsJsonArray().deepCopy() : new JsonArray();
    }

    public static Answer answer(JsonObject o) {
        String s = Models.text(o, "answer", null);
        if (s == null || s.isBlank() || s.length() > 8000) {
            throw new IllegalArgumentException("伺服器回答格式異常，請重試。");
        }
        return new Answer(Models.safe(s, 8000), Models.facts(o));
    }

    public static Message message(JsonObject o) {
        String role = Models.text(o, "role", "");
        if (!role.equals("user") && !role.equals("assistant")) {
            throw new IllegalArgumentException("訊息角色無效。");
        }
        String at = Models.text(o, "created_at", "");
        Instant.parse(at);
        return new Message(Models.uuid(Models.text(o, "id", null)), Models.uuid(Models.text(o, "conversation_id", null)), role, Models.safe(Models.text(o, "text", ""), 8000), Models.facts(o), at, true);
    }

    public static JsonObject obj(Object ... pairs) {
        JsonObject o = new JsonObject();
        for (int i = 0; i < pairs.length; i += 2) {
            Object v = pairs[i + 1];
            if (v instanceof JsonElement) {
                JsonElement j = (JsonElement)v;
                o.add((String)pairs[i], j.deepCopy());
                continue;
            }
            if (v instanceof Boolean) {
                Boolean b = (Boolean)v;
                o.addProperty((String)pairs[i], b);
                continue;
            }
            o.addProperty((String)pairs[i], String.valueOf(v));
        }
        return o;
    }

    private Models() {
    }

    public record Answer(String text, JsonArray facts) {
    }

    public record Message(String id, String conversationId, String role, String text, JsonArray facts, String createdAt, boolean synced) {
        public Message syncedCopy() {
            return new Message(this.id, this.conversationId, this.role, this.text, this.facts.deepCopy(), this.createdAt, true);

