package io.github.coyotewolf.aoi.model;

import io.github.coyotewolf.aoi.model.NearbyQuery;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;

public final class NearbySearch {
    public static List<Found> search(NearbyQuery query, double x, double y, double z, Iterable<Candidate> entities) {
        List<String> terms = Arrays.stream(query.query().toLowerCase(Locale.ROOT).split("[,，、]")).map(String::strip).filter(t -> !t.isEmpty()).toList();
        if (terms.isEmpty()) {
            throw new IllegalArgumentException("請指定實體。");
        }
        ArrayList<Found> found = new ArrayList<Found>();
        for (Candidate entity : entities) {
            double dz;
            double dy;
            double dx;
            double distance;
            String hay = (entity.id() + " " + entity.name() + " " + entity.extra()).toLowerCase(Locale.ROOT);
            if (!terms.stream().anyMatch(t -> t.contains(":") ? entity.id().equals(t) || Arrays.asList(entity.extra().split("\\s+")).contains(t) : hay.contains((CharSequence)t)) || !Double.isFinite(distance = Math.sqrt((dx = entity.x() - x) * dx + (dy = entity.y() - y) * dy + (dz = entity.z() - z) * dz)) || query.radius() != 0 && !(distance <= (double)query.radius())) continue;
            found.add(new Found(entity, distance, dx, dy, dz));
        }
        found.sort(Comparator.comparingDouble(Found::distance).thenComparing(f -> f.entity().id()).thenComparingDouble(f -> f.entity().x()).thenComparingDouble(f -> f.entity().z()));
        return List.copyOf(found);
    }

    public static String direction(double dx, double dz) {
        if (Math.hypot(dx, dz) < 1.0) {
            return "幾乎就在你的位置";
        }
        String[] names = new String[]{"北", "東北", "東", "東南", "南", "西南", "西", "西北"};
        int index = Math.floorMod((int)Math.round(Math.atan2(dx, -dz) / 0.7853981633974483), 8);
        return names[index] + "方";
    }

    private NearbySearch() {
    }

    public record Candidate(String id, String name, String extra, double x, double y, double z) {
    }

    public record Found(Candidate entity, double distance, double dx, double dy, double dz) {
    }
}

