package io.github.coyotewolf.aoi.model;

import io.github.coyotewolf.aoi.model.RegistryQuery;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;

public final class RegistryLookup {
    public static List<Entry> search(RegistryQuery query, List<Entry> entries) {
        String term = query.query().toLowerCase(Locale.ROOT);
        String english = term.replace(' ', '_');
        List<Entry> eligible = entries.stream().filter(e -> query.kind().equals("any") || e.kind().equals(query.kind())).distinct().toList();
        List<Entry> exact = eligible.stream().filter(e -> e.id().equalsIgnoreCase(term) || e.name().equalsIgnoreCase(term)).toList();
        if (!exact.isEmpty()) {
            return exact.stream().sorted(Comparator.comparing(Entry::id).thenComparing(Entry::kind)).toList();
        }
        return eligible.stream().filter(e -> e.name().toLowerCase(Locale.ROOT).contains(term) || e.id().toLowerCase(Locale.ROOT).contains(english)).sorted(Comparator.comparing(Entry::id).thenComparing(Entry::kind)).toList();
    }

    private RegistryLookup() {
    }

    public record Entry(String kind, String id, String name) {
    }
}

