package io.github.coyotewolf.aoi.security;

import com.google.gson.JsonObject;
import io.github.coyotewolf.aoi.model.Models;
import io.github.coyotewolf.aoi.security.SessionStore;
import java.time.Instant;
import java.util.concurrent.CancellationException;

public final class SessionManager {
    private volatile Session current;
    private volatile long generation;
    private final SessionStore store;
    private volatile String storageNotice = "";

    public SessionManager() {
        this(SessionStore.MEMORY);
    }

    public SessionManager(SessionStore store) {
        this.store = store;
        try {
            JsonObject saved = store.load();
            if (saved == null) {
                return;
            }
            String uid = Models.uuid(Models.text(saved, "user_id", null));
            String refresh = Models.text(saved, "refresh_token", "");
            if (refresh.isBlank() || refresh.length() > 16000) {
                throw new IllegalArgumentException();
            }
            this.current = new Session(uid, "", refresh, 0L);
        }
        catch (Exception e) {
            this.storageNotice = "保存的登入無法讀取，請重新登入。";
            try {
                store.delete();
            }
            catch (Exception ignored) {
                this.storageNotice = "保存的登入無法讀取或清除，請重新登入。";
            }
        }
    }

    public synchronized void clear() {
        this.current = null;
        ++this.generation;
        try {
            this.store.delete();
            this.storageNotice = "";
        }
        catch (Exception e) {
            this.storageNotice = "無法清除保存的登入資料；請檢查設定資料夾權限。";
        }
    }

    public synchronized void release() {
        this.current = null;
        ++this.generation;
    }

    public String storageNotice() {
        return this.storageNotice;
    }

    public Session get() {
        return this.current;
    }

    public long generation() {
        return this.generation;
    }

    public synchronized void install(JsonObject data, long expected) {
        if (this.generation != expected) {
            throw new CancellationException();
        }
        String access = Models.text(data, "access_token", "");
        String refresh = Models.text(data, "refresh_token", "");
        if (access.isBlank() || refresh.isBlank() || !data.has("user") || !data.get("user").isJsonObject()) {
            throw new IllegalArgumentException("登入資料格式異常。");
        }
        String uid = Models.uuid(Models.text(data.getAsJsonObject("user"), "id", null));
        if (this.current != null && !this.current.userId.equals(uid)) {
            throw new IllegalArgumentException("登入帳號已變更，請重新登入。");
        }
        long expiry = data.has("expires_at") ? data.get("expires_at").getAsLong() : Instant.now().getEpochSecond() + (data.has("expires_in") ? data.get("expires_in").getAsLong() : 3600L);
        this.current = new Session(uid, access, refresh, expiry);
        try {
            this.store.save(Models.obj("version", 1, "user_id", uid, "refresh_token", refresh));
            this.storageNotice = "";
        }
        catch (Exception e) {
            this.storageNotice = "本次已登入，但無法保存登入；重開遊戲需再登入。";
        }
    }

